//! A self-contained, simulated DNS lookup drawn in GPUI.
use crate::{
    foundation::Theme,
    primitives::{
        family::{Paint, PhaseClock, Slide, Tone, disabled_motion, face},
        glyph::{Glyph, icon},
        presentation::tr,
    },
};
use gpui::{prelude::*, *};
use std::{cell::Cell, f32::consts::TAU, rc::Rc, sync::OnceLock};

// Cue times measured from the public 16-second playback, rounded to tenths.
const MARKS: [f32; 7] = [0., 1.9, 4.1, 6.3, 8.4, 11., 16.];
const ANSWER: f32 = MARKS[4];
const CONNECTED: f32 = 10.3;
const HIT: f32 = 12.1;
const CACHED: f32 = 12.8;
const EXPIRE: f32 = 14.9;
const STEPS: [(&str, &str, &str, &str); 6] = [
    ("Ask", "查询", "Ask the resolver", "向解析器查询"),
    ("Root", "根", "Root server", "根服务器"),
    (".dev", "顶级域", "TLD server", "顶级域服务器"),
    (
        "Nameserver",
        "权威",
        "Authoritative nameserver",
        "权威域名服务器",
    ),
    ("Answer", "应答", "Answer and connect", "应答并建立连接"),
    ("Cache", "缓存", "Answered from cache", "从缓存应答"),
];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DnsNodeKind {
    Browser,
    Resolver,
    Root,
    Tld,
    Authoritative,
}

#[derive(Clone, Default)]
pub struct DnsNode {
    pub label: Option<SharedString>,
    pub meta: Option<SharedString>,
    pub detail: Option<SharedString>,
    pub icon: Option<Glyph>,
    pub color: Option<Hsla>,
    /// A host-supplied GPUI element factory for an image, custom path or other mark.
    pub mark: Option<Rc<dyn Fn() -> AnyElement>>,
}

#[derive(Clone)]
pub struct DnsResolutionOptions {
    pub domain: SharedString,
    pub address: SharedString,
    pub ttl: u32,
    pub lookup_ms: u32,
    pub cached_ms: u32,
    pub nodes: [DnsNode; 5],
    pub speed: f32,
    pub paused: bool,
    pub accent: Option<Hsla>,
    pub controls: bool,
    pub caption: bool,
    pub label: Option<SharedString>,
}

impl Default for DnsResolutionOptions {
    fn default() -> Self {
        Self {
            domain: "app.acme.dev".into(),
            address: "203.0.113.24".into(),
            ttl: 300,
            lookup_ms: 84,
            cached_ms: 1,
            nodes: Default::default(),
            speed: 1.,
            paused: false,
            accent: None,
            controls: true,
            caption: true,
            label: None,
        }
    }
}

impl DnsResolutionOptions {
    pub fn with_node(mut self, kind: DnsNodeKind, node: DnsNode) -> Self {
        self.nodes[kind as usize] = node;
        self
    }

    fn domains(&self) -> (&str, &str) {
        let name = self.domain.trim_end_matches('.');
        let Some((prefix, suffix)) = name.rsplit_once('.') else {
            return (name, name);
        };
        let base = prefix.rsplit_once('.').map_or(prefix, |(_, tail)| tail);
        (
            &name[name.len() - suffix.len() - 1..],
            &name[name.len() - base.len() - suffix.len() - 1..],
        )
    }
}

#[derive(Clone, Copy)]
struct Snapshot {
    time: f32,
    stage: usize,
    expired: bool,
}

impl Snapshot {
    fn at(time: f32) -> Self {
        let time = time.rem_euclid(MARKS[6]);
        Self {
            time,
            stage: MARKS[..6].partition_point(|mark| *mark <= time) - 1,
            expired: time >= EXPIRE,
        }
    }

    fn fraction(self, start: f32, end: f32) -> f32 {
        ((self.time - start) / (end - start)).clamp(0., 1.)
    }

    fn ttl(self) -> f32 {
        1. - self.fraction(ANSWER, EXPIRE).powf(1.17)
    }

    fn alpha(self) -> f32 {
        1. - self.fraction(15.62, 16.)
    }

    fn packet(self) -> Option<(usize, f32, bool, bool)> {
        // Each of the server hops carries a question out and a referral back.
        let (route, fraction, reverse) = match self.stage {
            0 => (0, self.fraction(0., MARKS[1] - 0.16), false),
            1..=3 => {
                let t = self.fraction(MARKS[self.stage], MARKS[self.stage + 1] - 0.15);
                (self.stage, 1. - (2. * t - 1.).abs(), t >= 0.5)
            }
            4 => (0, 1. - self.fraction(ANSWER + 0.14, CONNECTED), true),
            _ if self.time >= MARKS[5] + 0.14 && self.time < CACHED => {
                let t = self.fraction(MARKS[5] + 0.14, CACHED);
                (0, 1. - (2. * t - 1.).abs(), t >= 0.5)
            }
            _ => return None,
        };
        let eased = (1. - (std::f32::consts::PI * fraction).cos()) * 0.5;
        Some((route, eased, reverse, self.stage >= 4))
    }
}

type Coordinate = (f32, f32);

#[derive(Clone, Copy)]
struct Platform {
    x: f32,
    y: f32,
    half: f32,
    depth: f32,
    label: f32,
}

struct Geometry {
    size: Coordinate,
    nodes: [Platform; 5],
    routes: [Arc; 4],
}

struct Arc {
    start: Coordinate,
    control: Coordinate,
    end: Coordinate,
    lengths: [f32; 33],
}

impl Arc {
    fn new(start: Coordinate, control: Coordinate, end: Coordinate) -> Self {
        let mut route = Self {
            start,
            control,
            end,
            lengths: [0.; 33],
        };
        let mut last = start;
        for i in 1..route.lengths.len() {
            let next = route.point(i as f32 / 32.);
            route.lengths[i] = route.lengths[i - 1] + (next.0 - last.0).hypot(next.1 - last.1);
            last = next;
        }
        route
    }

    fn point(&self, t: f32) -> Coordinate {
        let s = 1. - t;
        let a = s * s;
        let b = 2. * s * t;
        let c = t * t;
        (
            a * self.start.0 + b * self.control.0 + c * self.end.0,
            a * self.start.1 + b * self.control.1 + c * self.end.1,
        )
    }

    fn at(&self, progress: f32) -> Coordinate {
        let distance = self.lengths[32] * progress.clamp(0., 1.);
        let i = self.lengths.partition_point(|x| *x < distance).clamp(1, 32);
        let offset = (distance - self.lengths[i - 1]) / (self.lengths[i] - self.lengths[i - 1]);
        self.point((i as f32 - 1. + offset) / 32.)
    }
}

fn geometry(narrow: bool) -> &'static Geometry {
    static WIDE: OnceLock<Geometry> = OnceLock::new();
    static NARROW: OnceLock<Geometry> = OnceLock::new();
    let cache = if narrow { &NARROW } else { &WIDE };
    cache.get_or_init(|| {
        let (size, positions, bends) = if narrow {
            (
                (390., 676.),
                [
                    (104., 122., 62., 12., 38.),
                    (112., 452., 70., 18., 517.),
                    (294., 104., 50., 22., 163.),
                    (294., 318., 50., 22., 377.),
                    (294., 532., 50., 22., 591.),
                ],
                [(44., 251.), (163., 202.), (193., 303.), (223., 446.)],
            )
        } else {
            (
                (1000., 612.),
                [
                    (160., 290., 74., 14., 353.),
                    (480., 290., 84., 20., 364.),
                    (850., 80., 58., 26., 147.),
                    (850., 272., 58., 26., 339.),
                    (850., 464., 58., 26., 531.),
                ],
                [(320., 166.), (625., 87.), (665., 171.), (689., 311.)],
            )
        };
        let nodes = positions.map(|(x, y, half, depth, label)| Platform {
            x,
            y,
            half,
            depth,
            label,
        });
        let resolver = (nodes[1].x, nodes[1].y - 12.);
        let routes = std::array::from_fn(|i| {
            let n = nodes[if i == 0 { 0 } else { i + 1 }];
            if i == 0 {
                Arc::new((n.x, n.y), bends[i], resolver)
            } else {
                Arc::new(resolver, bends[i], (n.x, n.y))
            }
        });
        Geometry {
            size,
            nodes,
            routes,
        }
    })
}

type Refine = Box<dyn Fn(Div) -> Div>;
type Visibility = Box<dyn Fn(&App) -> bool>;

pub struct DnsResolution {
    options: DnsResolutionOptions,
    elapsed: f32,
    age: f32,
    clock: PhaseClock,
    pace: Slide,
    paused: bool,
    visible: bool,
    visibility: Option<Visibility>,
    hovered: Option<usize>,
    step: Option<usize>,
    width: Rc<Cell<Pixels>>,
    focus: [FocusHandle; 6],
    id: ElementId,
    style: Option<Refine>,
}

impl DnsResolution {
    pub fn new(options: DnsResolutionOptions, cx: &mut Context<Self>) -> Self {
        let paused = options.paused;
        Self {
            elapsed: if paused { CACHED } else { 0. },
            pace: Slide::new(if paused { 0. } else { speed(options.speed) }),
            options,
            age: 0.,
            clock: PhaseClock::default(),
            paused,
            visible: true,
            visibility: None,
            hovered: None,
            step: None,
            width: Rc::default(),
            focus: std::array::from_fn(|_| cx.focus_handle()),
            id: "dns-resolution".into(),
            style: None,
        }
    }

    pub fn with_id(mut self, id: impl Into<ElementId>) -> Self {
        self.id = id.into();
        self
    }

    pub fn with_style(mut self, style: impl Fn(Div) -> Div + 'static) -> Self {
        self.style = Some(Box::new(style));
        self
    }

    pub fn with_visibility(mut self, visible: impl Fn(&App) -> bool + 'static) -> Self {
        self.visibility = Some(Box::new(visible));
        self
    }

    pub fn set_visible(&mut self, visible: bool, cx: &mut Context<Self>) {
        if self.visible != visible {
            self.visible = visible;
            self.clock = PhaseClock::default();
            cx.notify();
        }
    }

    pub fn set_speed(&mut self, value: f32, cx: &mut Context<Self>) {
        self.options.speed = speed(value);
        self.retarget(cx);
    }

    pub fn set_paused(&mut self, paused: bool, cx: &mut Context<Self>) {
        self.paused = paused;
        if !paused {
            self.step = None;
        }
        self.retarget(cx);
    }

    pub fn seek(&mut self, stage: usize, cx: &mut Context<Self>) {
        let stage = stage.min(5);
        self.step = Some(stage);
        self.elapsed = MARKS[stage];
        self.clock = PhaseClock::default();
        if self.paused {
            self.pace.reset(0.);
        }
        cx.notify();
    }

    fn retarget(&mut self, cx: &mut Context<Self>) {
        let pace = if self.paused {
            0.
        } else {
            speed(self.options.speed)
        };
        self.pace.set(
            if self.hovered.is_some() {
                pace * 0.55
            } else {
                pace
            },
            cx,
        );
        cx.notify();
    }

    fn snapshot(&mut self, window: &Window, cx: &App) -> Snapshot {
        let reduced = disabled_motion(cx);
        if !self.visible
            || !window.is_visible()
            || reduced
            || self.visibility.as_ref().is_some_and(|visible| !visible(cx))
        {
            self.clock = PhaseClock::default();
            if reduced {
                return Snapshot::at(
                    self.step
                        .map_or(CACHED, |step| (MARKS[step] + MARKS[step + 1]) / 2.),
                );
            }
        } else {
            if !self.clock.age(cx).is_finite() {
                self.clock.restart(cx);
                self.age = 0.;
            }
            let age = self.clock.age(cx);
            let (pace, moving) = self
                .pace
                .sample_batch(cx.background_executor().now(), false);
            self.elapsed =
                (self.elapsed + (age - self.age).max(0.) * pace.max(0.)).rem_euclid(MARKS[6]);
            self.age = age;
            if moving || pace > 0. {
                window.request_animation_frame();
            }
        }
        Snapshot::at(self.elapsed)
    }
}

fn speed(value: f32) -> f32 {
    if value.is_finite() { value.max(0.) } else { 1. }
}

fn draw_shape(w: &mut Window, points: &[Point<Pixels>], fill_color: Option<Hsla>, ink: Hsla) {
    if let Some(color) = fill_color {
        let mut path = PathBuilder::fill();
        path.move_to(points[0]);
        for point in &points[1..] {
            path.line_to(*point);
        }
        path.close();
        if let Ok(path) = path.build() {
            w.paint_path(path, color);
        }
    }
    let mut outline = PathBuilder::stroke(px(1.));
    outline.move_to(points[0]);
    for point in &points[1..] {
        outline.line_to(*point);
    }
    if fill_color.is_some() {
        outline.close();
    }
    if let Ok(path) = outline.build() {
        w.paint_path(path, ink);
    }
}

fn draw_platform(
    w: &mut Window,
    at: impl Fn(Coordinate) -> Point<Pixels>,
    n: Platform,
    paint: Paint,
) {
    let Platform {
        x, y, half, depth, ..
    } = n;
    let fore = y + half * 0.5;
    let top = [(x, y - half * 0.5), (x + half, y), (x, fore), (x - half, y)];
    let left = [top[3], top[2], (x, fore + depth), (x - half, y + depth)];
    let right = [top[2], top[1], (x + half, y + depth), (x, fore + depth)];
    let line = paint.ink.opacity(0.19);
    draw_shape(w, &left.map(&at), Some(paint.tray), line);
    draw_shape(w, &right.map(&at), Some(paint.hover), line);
    draw_shape(w, &top.map(at), Some(paint.panel), line);
}

fn dot(w: &mut Window, point: Point<Pixels>, radius: f32, color: Hsla) {
    let r = px(radius);
    w.paint_quad(
        fill(
            Bounds::new(point - gpui::point(r, r), size(r * 2., r * 2.)),
            color,
        )
        .corner_radii(r),
    );
}

fn draw_scene(
    w: &mut Window,
    b: Bounds<Pixels>,
    geo: &Geometry,
    frame: Snapshot,
    p: Paint,
    accent: Hsla,
    reduced: bool,
) {
    let (width, height) = geo.size;
    let at = |(x, y): Coordinate| {
        point(
            b.origin.x + b.size.width * (x / width),
            b.origin.y + b.size.height * (y / height),
        )
    };
    let mut ground = PathBuilder::stroke(px(1.));
    for i in 0..geo.routes.len() {
        let a = geo.nodes[if i == 0 { 0 } else { 1 }];
        let z = geo.nodes[if i == 0 { 1 } else { i + 1 }];
        for j in (0..24).step_by(2) {
            let floor = |t: f32| {
                at((
                    a.x + (z.x - a.x) * t,
                    a.y + a.depth + (z.y + z.depth - a.y - a.depth) * t,
                ))
            };
            ground.move_to(floor(j as f32 / 24.));
            ground.line_to(floor((j + 1) as f32 / 24.));
        }
    }
    if let Ok(path) = ground.build() {
        w.paint_path(path, p.ink.opacity(0.06));
    }
    for i in [2, 3, 0, 1, 4] {
        let n = geo.nodes[i];
        draw_platform(w, at, n, p);
        if i == 1 {
            draw_platform(
                w,
                at,
                Platform {
                    half: n.half * 0.58,
                    y: n.y - 12.,
                    depth: 12.,
                    ..n
                },
                p,
            );
            let center = at((n.x, n.y - 12.));
            let scale = b.size.width / px(width);
            let r = 30. * scale;
            for (fraction, color) in [
                (1., p.ink.opacity(0.09)),
                (
                    if frame.time >= ANSWER {
                        frame.ttl()
                    } else {
                        0.
                    },
                    accent.opacity(frame.alpha()),
                ),
            ] {
                if fraction > 0. {
                    let mut line = PathBuilder::stroke(px(1.));
                    let count = (fraction * 32.).ceil() as usize;
                    for j in 0..=count {
                        let a = TAU * fraction * j as f32 / count as f32 - TAU / 4.;
                        let point = center + point(px(a.cos() * r), px(a.sin() * r * 0.5));
                        if j == 0 {
                            line.move_to(point);
                        } else {
                            line.line_to(point);
                        }
                    }
                    if let Ok(path) = line.build() {
                        w.paint_path(path, color);
                    }
                }
            }
        } else if i == 0 {
            let (x, y, h) = (n.x, n.y, n.half);
            for j in 0..if frame.time >= CONNECTED { 5 } else { 3 } {
                let shift = j as f32 * h * 0.14;
                draw_shape(
                    w,
                    &[
                        at((x - h * 0.13 - shift, y - h * 0.33 + shift * 0.5)),
                        at((x + h * 0.64 - shift, y + h * 0.055 + shift * 0.5)),
                    ],
                    None,
                    p.ink
                        .opacity(0.08 + if frame.time >= CONNECTED { 0.05 } else { 0. }),
                );
            }
        } else {
            let x = n.x + n.half * 0.8;
            dot(w, at((x, n.y + n.depth * 0.58)), 1.5, p.ink.opacity(0.22));
        }
    }
    for (i, route) in geo.routes.iter().enumerate() {
        let mut path = PathBuilder::stroke(px(1.));
        path.move_to(at(route.start));
        path.curve_to(at(route.end), at(route.control));
        if let Ok(path) = path.build() {
            let ink = if frame.stage > i {
                accent.opacity(0.32 * frame.alpha())
            } else {
                p.ink.opacity(0.19)
            };
            w.paint_path(path, ink);
        }
        let port = if i == 0 { route.start } else { route.end };
        dot(w, at(port), 2., p.ink.opacity(0.27));
        dot(w, at(port), 1., p.panel);
    }
    if !reduced && let Some((index, progress, reverse, _)) = frame.packet() {
        let route = &geo.routes[index];
        let (x, y) = route.at(progress);
        let floor = route.start.1 + (route.end.1 - route.start.1) * progress + 25.;
        dot(
            w,
            at((x, floor)),
            (3.8 - (floor - y).abs() * 0.02).clamp(1.4, 3.8),
            p.ink.opacity(0.13),
        );
        for i in (1..=5).rev() {
            let delta = i as f32 * 0.009 * if reverse { 1. } else { -1. };
            dot(
                w,
                at(route.at(progress + delta)),
                2.3,
                accent.opacity((6 - i) as f32 * 0.1),
            );
        }
        dot(w, at((x, y)), 3.5, accent);
    }
}

impl DnsResolution {
    fn node_meta(&self, index: usize, tld: &str, base: &str) -> SharedString {
        self.options.nodes[index]
            .meta
            .clone()
            .unwrap_or_else(|| match index {
                0 => self.options.domain.clone(),
                1 => "1.1.1.1".into(),
                2 => "a.root-servers.net".into(),
                3 => format!("{tld} registry").into(),
                _ => format!("ns1.{base}").into(),
            })
    }

    fn statuses(
        &self,
        frame: Snapshot,
        tld: &str,
        nameserver: &str,
        cx: &App,
    ) -> [SharedString; 5] {
        let o = &self.options;
        let lookup = if frame.time >= CACHED {
            format!("{} {} ms", tr(cx, "Connected in", "连接耗时"), o.cached_ms)
        } else if frame.time >= CONNECTED {
            format!("{} {} ms", tr(cx, "Connected in", "连接耗时"), o.lookup_ms)
        } else {
            let ms = (o.lookup_ms as f32 * frame.fraction(0.36, 9.6)).round() as u32;
            format!("{} {ms} ms", tr(cx, "Resolving", "解析中"))
        };
        let resolver = match frame.time {
            t if t >= EXPIRE => tr(cx, "Expired", "已过期").to_string(),
            t if t >= HIT => tr(cx, "Cache hit", "命中缓存").to_string(),
            t if t >= ANSWER => tr(cx, "Answer cached", "应答已缓存").to_string(),
            t if t >= MARKS[3] => tr(cx, "Asking nameserver", "查询权威服务器").to_string(),
            t if t >= MARKS[2] => format!("{} {tld}", tr(cx, "Asking", "查询")),
            t if t >= MARKS[1] + 0.06 => tr(cx, "Asking root", "查询根服务器").to_string(),
            t if t >= 1.7 => tr(cx, "Not cached", "尚未缓存").to_string(),
            _ => tr(cx, "Waiting", "等待").to_string(),
        };
        let waiting = tr(cx, "Looking up", "查询中");
        [
            lookup.into(),
            resolver.into(),
            if frame.stage >= 2 {
                format!("{} {tld}", tr(cx, "Try", "转向")).into()
            } else {
                waiting.into()
            },
            if frame.stage >= 3 {
                format!("{} {nameserver}", tr(cx, "Try", "转向")).into()
            } else {
                waiting.into()
            },
            if frame.stage >= 4 {
                o.address.clone()
            } else {
                waiting.into()
            },
        ]
    }

    fn caption(&self, stage: usize, tld: &str, base: &str, ns: &str, cx: &App) -> String {
        let o = &self.options;
        if crate::primitives::control::UiLanguage::current(cx)
            == crate::primitives::control::UiLanguage::Chinese
        {
            return match stage {
                0 => format!("浏览器向解析器查询 {}。缓存中还没有这条记录。", o.domain),
                1 => format!("根服务器不知道地址，它会指向 {tld} 的服务器。"),
                2 => format!("{tld} 服务器指向 {base} 的权威域名服务器 {ns}。"),
                3 => format!("{ns} 返回地址 {}。", o.address),
                4 => format!(
                    "解析器将应答缓存 {} 秒，浏览器在 {} ms 内建立连接。",
                    o.ttl, o.lookup_ms
                ),
                _ => format!(
                    "TTL 到期之前，下次查询直接从缓存应答，耗时 {} ms。",
                    o.cached_ms
                ),
            };
        }
        match stage {
            0 => format!(
                "Your browser asks the resolver for {}. It is not in the cache yet.",
                o.domain
            ),
            1 => format!("The root server points the resolver to the {tld} servers."),
            2 => format!("The {tld} server points to {ns}, the nameserver for {base}."),
            3 => format!("{ns} answers with the address {}.", o.address),
            4 => format!(
                "The resolver caches the answer for {} s and the browser connects in {} ms.",
                o.ttl, o.lookup_ms
            ),
            _ => format!(
                "The next lookup comes straight from the cache in {} ms, until the TTL runs out.",
                o.cached_ms
            ),
        }
    }
}

impl Render for DnsResolution {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let p = Paint::get(cx);
        let radius = Theme::global(cx).tokens.radius.md;
        let accent = self.options.accent.unwrap_or(p.bright);
        let width = match self.width.get() {
            width if width > px(0.) => f32::from(width),
            _ => f32::from(w.viewport_size().width).clamp(240., 1000.),
        };
        let narrow = width < 640.;
        let geo = geometry(narrow);
        let scale = width / geo.size.0;
        let height = geo.size.1 * scale;
        let reduced = disabled_motion(cx);
        let frame = self.snapshot(w, cx);
        let stage = frame.stage;
        let (tld, base) = self.options.domains();
        let nameserver = self.node_meta(4, tld, base);
        let statuses = self.statuses(frame, tld, &nameserver, cx);
        let label_width = width * if narrow { 0.47 } else { 0.29 };
        let mut label_tops = geo.nodes.map(|node| node.label * scale);
        if narrow {
            let browser = geo.nodes[0];
            let platform_top = (browser.y - browser.half * 0.5) * scale;
            label_tops[0] = label_tops[0].min((platform_top - 58.).max(0.));
        }
        let lang = crate::primitives::control::UiLanguage::current(cx);
        let labels = [
            lang.text("Browser", "浏览器"),
            lang.text("Resolver", "解析器"),
            lang.text("Root server", "根服务器"),
            lang.text("TLD server", "顶级域服务器"),
            lang.text("Nameserver", "权威域名服务器"),
        ];
        let description = self.options.label.clone().unwrap_or_else(|| {
            format!(
                "{} {} · {} → {} → {} → {} → {} · {} · {} ms · TTL {} s · {} {} ms",
                lang.text("DNS resolution for", "DNS 解析"),
                self.options.domain,
                labels[0],
                labels[1],
                labels[2],
                tld,
                nameserver,
                self.options.address,
                self.options.lookup_ms,
                self.options.ttl,
                lang.text("Cache hit", "命中缓存"),
                self.options.cached_ms
            )
            .into()
        });
        let scene = div()
            .id("dns-scene")
            .debug_selector(|| "dns-scene".into())
            .role(Role::Image)
            .aria_label(description)
            .relative()
            .w_full()
            .h(px(height))
            .flex_none()
            .child(
                canvas(
                    |_, _, _| {},
                    move |b, _, w, _| draw_scene(w, b, geo, frame, p, accent, reduced),
                )
                .absolute()
                .inset_0()
                .size_full(),
            )
            .children(geo.nodes.iter().enumerate().map(|(i, n)| {
                let node = &self.options.nodes[i];
                let meta = self.node_meta(i, tld, base);
                let label = node.label.clone().unwrap_or_else(|| labels[i].into());
                let show_status = i < 2 || stage >= i - 1;
                let color = node.color.unwrap_or(p.ink);
                let hover = self.hovered == Some(i);
                let ready = match i {
                    0 => frame.time >= CONNECTED,
                    1 => frame.time >= ANSWER && !frame.expired,
                    4 => stage >= 4,
                    _ => false,
                };
                let detail = node.detail.clone().unwrap_or_else(|| {
                    let defaults = [
                        lang.text(
                            "Needs an address before it can connect",
                            "需要地址才能建立连接",
                        ),
                        lang.text("Finds and caches the answer", "查询并缓存应答"),
                        lang.text("Points to top-level domain servers", "指向顶级域服务器"),
                        lang.text(
                            "Points to the authoritative nameserver",
                            "指向权威域名服务器",
                        ),
                        lang.text("Holds the address record", "保存地址记录"),
                    ];
                    defaults[i].into()
                });
                let hit_top = (n.y - n.half * 0.5) * scale;
                let top = hit_top.min(label_tops[i]);
                let label_y = label_tops[i] - top;
                div()
                    .id(("dns-node", i))
                    .absolute()
                    .top(px(top))
                    .left(px(n.x * scale - label_width * 0.5))
                    .w(px(label_width))
                    .pt(px(label_y))
                    .flex()
                    .flex_col()
                    .items_center()
                    .gap(px(2.))
                    .text_color(color)
                    .line_height(px(18.))
                    .on_hover(cx.listener(move |s, over: &bool, _, cx| {
                        if *over {
                            s.hovered = Some(i);
                        } else if s.hovered == Some(i) {
                            s.hovered = None;
                        }
                        s.retarget(cx);
                    }))
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .gap(px(4.))
                            .max_w_full()
                            .when_some(node.mark.clone(), |e, mark| e.child(mark()))
                            .when_some(node.icon, |e, glyph| e.child(icon(glyph, 12., color)))
                            .child(
                                div()
                                    .min_w(px(0.))
                                    .overflow_hidden()
                                    .whitespace_nowrap()
                                    .text_ellipsis()
                                    .font_weight(FontWeight::MEDIUM)
                                    .child(label),
                            ),
                    )
                    .when(narrow || width >= 720., |e| {
                        e.child(
                            div()
                                .max_w_full()
                                .overflow_hidden()
                                .whitespace_nowrap()
                                .text_ellipsis()
                                .text_size(px(12.))
                                .line_height(px(16.))
                                .text_color(p.secondary)
                                .child(meta),
                        )
                    })
                    .when(show_status, |e| {
                        e.child(
                            div()
                                .flex()
                                .items_center()
                                .gap(px(4.))
                                .max_w_full()
                                .px(px(5.))
                                .rounded(radius)
                                .border_1()
                                .border_color(p.line)
                                .bg(p.panel)
                                .text_size(px(11.))
                                .line_height(px(16.))
                                .text_color(if ready { p.ink } else { p.secondary })
                                .child(div().size(px(4.)).flex_none().rounded_full().bg(if ready {
                                    p.success
                                } else {
                                    p.faint.opacity(0.65)
                                }))
                                .child(
                                    div()
                                        .min_w(px(0.))
                                        .overflow_hidden()
                                        .whitespace_nowrap()
                                        .text_ellipsis()
                                        .child(statuses[i].clone()),
                                ),
                        )
                    })
                    .when(i == 1 && frame.time >= ANSWER, |e| {
                        let ttl = if frame.expired {
                            lang.text("Expired", "已过期").to_string()
                        } else {
                            format!(
                                "TTL {} s",
                                (self.options.ttl as f32 * frame.ttl()).ceil() as u32
                            )
                        };
                        e.child(
                            div()
                                .mt(px(6.))
                                .w(px(if narrow { 152. } else { 184. }))
                                .max_w_full()
                                .px(px(8.))
                                .py(px(5.))
                                .rounded(radius)
                                .border_1()
                                .border_color(p.line)
                                .bg(p.panel)
                                .opacity(frame.alpha())
                                .flex()
                                .flex_col()
                                .gap(px(2.))
                                .text_size(px(11.))
                                .line_height(px(14.))
                                .child(
                                    div()
                                        .max_w_full()
                                        .overflow_hidden()
                                        .whitespace_nowrap()
                                        .text_ellipsis()
                                        .text_color(p.secondary)
                                        .child(self.options.domain.clone()),
                                )
                                .child(
                                    div()
                                        .flex()
                                        .flex_wrap()
                                        .justify_between()
                                        .gap(px(3.))
                                        .child(
                                            div()
                                                .max_w_full()
                                                .overflow_hidden()
                                                .whitespace_nowrap()
                                                .text_ellipsis()
                                                .child(format!("A {}", self.options.address)),
                                        )
                                        .child(div().text_color(p.secondary).child(ttl)),
                                ),
                        )
                    })
                    .when(hover, |e| {
                        e.child(
                            div()
                                .absolute()
                                .left_0()
                                .right_0()
                                .top(px(-13.))
                                .px(px(4.))
                                .text_center()
                                .text_size(px(10.))
                                .line_height(px(13.))
                                .text_color(p.secondary)
                                .child(detail),
                        )
                    })
            }))
            .when_some(
                if reduced { None } else { frame.packet() },
                |e, (index, progress, reverse, answer)| {
                    let (x, y) = geo.routes[index].at(progress);
                    let record = if answer && reverse {
                        format!("A {}", self.options.address)
                    } else if reverse && index == 1 {
                        format!("NS {tld}")
                    } else if reverse && index == 2 {
                        format!("NS {nameserver}")
                    } else if reverse && index == 3 {
                        format!("A {}", self.options.address)
                    } else {
                        format!("A? {}", self.options.domain)
                    };
                    let chip = (width * 0.37).clamp(92., 142.);
                    let left = (x * scale - chip * 0.5).clamp(0., (width - chip).max(0.));
                    let offset = if narrow && index == 0 { 11. } else { -31. };
                    let top = (y * scale + offset).clamp(0., (height - 22.).max(0.));
                    // Fade the tag near node readouts without changing the packet's path.
                    let opacity = geo
                        .nodes
                        .iter()
                        .enumerate()
                        .fold(1.0_f32, |opacity, (i, n)| {
                            let dx = (left + chip * 0.5 - n.x * scale).abs()
                                - (chip + label_width) * 0.5;
                            let label_top = label_tops[i];
                            let label_height = if i == 1 && frame.time >= ANSWER {
                                122.
                            } else {
                                56.
                            };
                            let dy = (top - label_top - label_height).max(label_top - top - 22.);
                            opacity.min((dx.max(dy) / 7.).clamp(0., 1.))
                        });
                    e.child(
                        div()
                            .absolute()
                            .left(px(left))
                            .top(px(top))
                            .w(px(chip))
                            .px(px(5.))
                            .h(px(22.))
                            .opacity(opacity)
                            .flex()
                            .items_center()
                            .justify_center()
                            .rounded(radius)
                            .bg(p.panel)
                            .border_1()
                            .border_color(p.line)
                            .text_color(p.ink)
                            .text_size(px(11.))
                            .child(
                                div()
                                    .min_w(px(0.))
                                    .overflow_hidden()
                                    .whitespace_nowrap()
                                    .text_ellipsis()
                                    .child(record),
                            ),
                    )
                },
            );
        let width_cell = self.width.clone();
        let controls = self.options.controls;
        let caption = self.options.caption;
        let label = STEPS[stage];
        let paused = self.paused || reduced;
        let root = div()
            .w_full()
            .max_w(px(1000.))
            .min_w(px(0.))
            .flex()
            .flex_col()
            .items_center()
            .gap(px(12.));
        let root = if let Some(style) = &self.style {
            style(root)
        } else {
            root
        };
        root.on_children_prepainted(move |children, w, _| {
            if let Some(stage) = children.first()
                && stage.size.width != width_cell.replace(stage.size.width)
            {
                w.request_animation_frame();
            }
        })
        .id(self.id.clone())
        .child(scene)
        .when(controls, |e| {
            e.child(
                div()
                    .id("dns-scrubber")
                    .role(Role::Group)
                    .aria_label(lang.text("Lookup steps", "解析步骤"))
                    .w_full()
                    .max_w(px(640.))
                    .px(px(4.))
                    .flex()
                    .items_center()
                    .gap(px(6.))
                    .child(
                        face(
                            "dns-playback",
                            if paused {
                                lang.text("Play", "播放")
                            } else {
                                lang.text("Pause", "暂停")
                            },
                            36.,
                            f32::from(radius),
                            Tone::Clear,
                            cx,
                        )
                        .w(px(36.))
                        .border_1()
                        .border_color(p.line)
                        .aria_toggled(paused.into())
                        .when(reduced, |e| e.tab_stop(false).opacity(0.5))
                        .child(icon(
                            if paused { Glyph::Play } else { Glyph::Pause },
                            14.,
                            p.secondary,
                        ))
                        .on_click(cx.listener(|s, _, _, cx| {
                            if !disabled_motion(cx) {
                                s.set_paused(!s.paused, cx);
                            }
                        })),
                    )
                    .children(
                        STEPS
                            .iter()
                            .enumerate()
                            .map(|(i, (en, zh, title, title_zh))| {
                                let label = if i == 2
                                    && lang != crate::primitives::control::UiLanguage::Chinese
                                {
                                    tld
                                } else {
                                    lang.text(en, zh)
                                };
                                let progress = frame.fraction(MARKS[i], MARKS[i + 1]);
                                face(
                                    ("dns-step", i),
                                    format!(
                                        "{} {}/6 · {}",
                                        lang.text("Step", "步骤"),
                                        i + 1,
                                        lang.text(title, title_zh)
                                    ),
                                    44.,
                                    f32::from(radius),
                                    Tone::Clear,
                                    cx,
                                )
                                .track_focus(&self.focus[i])
                                .flex_1()
                                .min_w(px(0.))
                                .flex_col()
                                .gap(px(3.))
                                .text_size(px(11.))
                                .text_color(if i == stage { p.ink } else { p.secondary })
                                .aria_toggled((i == stage).into())
                                .child(
                                    div().h(px(3.)).w_full().rounded_full().bg(p.line).child(
                                        div()
                                            .h_full()
                                            .w(relative(progress))
                                            .rounded_full()
                                            .bg(accent),
                                    ),
                                )
                                .when(!narrow, |e| {
                                    e.child(
                                        div()
                                            .max_w_full()
                                            .overflow_hidden()
                                            .text_ellipsis()
                                            .child(label.to_string()),
                                    )
                                })
                                .on_click(cx.listener(move |s, _, _, cx| s.seek(i, cx)))
                                .on_key_down(cx.listener(
                                    move |s, event: &KeyDownEvent, w, cx| {
                                        let next = match event.keystroke.key.as_str() {
                                            "left" => i.saturating_sub(1),
                                            "right" => (i + 1).min(5),
                                            "home" => 0,
                                            "end" => 5,
                                            _ => return,
                                        };
                                        s.seek(next, cx);
                                        s.focus[next].focus(w, cx);
                                        w.prevent_default();
                                        cx.stop_propagation();
                                    },
                                ))
                            }),
                    ),
            )
        })
        .when(caption, |e| {
            e.child(
                div()
                    .w_full()
                    .min_h(px(66.))
                    .px(px(8.))
                    .flex()
                    .flex_col()
                    .gap(px(4.))
                    .items_center()
                    .text_center()
                    .text_size(px(13.))
                    .line_height(px(18.))
                    .child(
                        div()
                            .font_weight(FontWeight::MEDIUM)
                            .text_color(p.ink)
                            .child(lang.text(label.2, label.3)),
                    )
                    .child(div().text_color(p.secondary).child(self.caption(
                        stage,
                        tld,
                        base,
                        &nameserver,
                        cx,
                    ))),
            )
        })
    }
}

#[cfg(test)]
mod tests {
    use super::{
        CACHED, DnsNode, DnsNodeKind, DnsResolution, DnsResolutionOptions, EXPIRE, MARKS, Snapshot,
        geometry, speed,
    };
    use gpui::{TestAppContext, px, size};

    #[test]
    fn clock_maps_each_chapter_and_cache_expiry_without_drift() {
        for (i, time) in MARKS[..6].iter().enumerate() {
            assert_eq!(Snapshot::at(*time).stage, i);
        }
        assert_eq!(Snapshot::at(16.).stage, 0);
        assert_eq!(Snapshot::at(CACHED).stage, 5);
        assert!(Snapshot::at(CACHED).packet().is_none());
        assert!(Snapshot::at(MARKS[5]).packet().is_none());
        assert!(Snapshot::at(CACHED).ttl() > 0.);
        assert!(Snapshot::at(EXPIRE).expired);
        assert_eq!(Snapshot::at(EXPIRE).ttl(), 0.);
        assert!(Snapshot::at(15.9).alpha() < 0.3);
    }

    #[test]
    fn layouts_switch_routes_and_keep_arc_lengths_monotonic() {
        for narrow in [false, true] {
            let geometry = geometry(narrow);
            for (i, route) in geometry.routes.iter().enumerate() {
                assert_eq!(route.at(0.), route.start);
                assert_eq!(route.at(1.), route.end);
                assert!(route.lengths.windows(2).all(|w| w[0] < w[1]));
                let node = geometry.nodes[i + 1];
                let endpoint = if i == 0 {
                    (node.x, node.y - 12.)
                } else {
                    (node.x, node.y)
                };
                assert_eq!(route.end, endpoint);
            }
        }
    }

    #[test]
    fn keyboard_seeks_paused_chapters_and_responsive_stage_fits() {
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let (control, window) = app.add_window_view(|_, cx| {
            let options = DnsResolutionOptions {
                paused: true,
                ..Default::default()
            };
            DnsResolution::new(options, cx)
        });
        for (width, expected) in [(320., 676. * 320. / 390.), (720., 612. * 720. / 1000.)] {
            window.simulate_resize(size(px(width), px(950.)));
            for _ in 0..2 {
                window.update(|w, cx| {
                    w.simulate_next_frame(cx);
                    w.refresh();
                });
                window.run_until_parked();
            }
            let bounds = window.debug_bounds("dns-scene").unwrap();
            assert_eq!(bounds.size.width, px(width));
            assert!((f32::from(bounds.size.height) - expected).abs() < 1.);
        }
        window.update(|w, cx| {
            let focus = control.read(cx).focus[1].clone();
            focus.focus(w, cx);
        });
        window.simulate_keystrokes("end");
        assert_eq!(window.update(|_, cx| control.read(cx).step), Some(5));
        window.simulate_keystrokes("left");
        assert_eq!(window.update(|_, cx| control.read(cx).step), Some(4));
        window.simulate_keystrokes("home");
        assert_eq!(window.update(|_, cx| control.read(cx).step), Some(0));
        assert!(window.update(|_, cx| control.read(cx).paused));
        window.update(|_, cx| control.update(cx, |s, cx| s.set_paused(false, cx)));
        window.simulate_keystrokes("end");
        assert!(!window.update(|_, cx| control.read(cx).paused));
        window.update(|_, cx| {
            control.update(cx, |s, cx| {
                s.pace.reset(1.);
                s.set_paused(true, cx);
                s.seek(5, cx);
                assert_eq!(s.pace.value(cx), 0.);
                assert_eq!(s.elapsed, MARKS[5]);
            });
        });
    }

    #[test]
    fn public_defaults_and_overrides_use_the_same_record() {
        let o = DnsResolutionOptions::default();
        assert_eq!(o.domains(), (".dev", "acme.dev"));
        assert_eq!((o.ttl, o.lookup_ms, o.cached_ms), (300, 84, 1));
        let o = DnsResolutionOptions {
            domain: "example.test.".into(),
            ..o
        }
        .with_node(
            DnsNodeKind::Authoritative,
            DnsNode {
                meta: Some("ns.example.test".into()),
                ..Default::default()
            },
        );
        assert_eq!(o.domains(), (".test", "example.test"));
        assert_eq!(o.nodes[4].meta.as_deref(), Some("ns.example.test"));
        assert_eq!(speed(0.), 0.);
        assert_eq!(speed(f32::NAN), 1.);
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

/// Optional host writing direction; left-to-right is the default. GPUI has no
/// direction property, so controls that place things on an inline axis read
/// this the way the Web reads `getComputedStyle(...).direction`.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiDirection {
    #[default]
    Ltr,
    Rtl,
}
impl gpui::Global for UiDirection {}
impl UiDirection {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn is_rtl(self) -> bool {
        matches!(self, Self::Rtl)
    }
    /// Reverse the inline step when the reading direction runs the other way.
    pub fn inline_step(self, step: isize) -> isize {
        if self.is_rtl() { -step } else { step }
    }
}

//! Compact action surfaces scoped to the button family.
use crate::foundation::{AccentPalette, Theme, ThemeMode};
use gpui::{prelude::*, *};
use web_time::Instant;
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tone {
    #[default]
    Surface,
    Primary,
    Muted,
    Danger,
    Success,
    Clear,
}
#[derive(Clone, Copy)]
pub struct Paint {
    pub stage: Hsla,
    pub panel: Hsla,
    pub tray: Hsla,
    pub hover: Hsla,
    pub ink: Hsla,
    pub secondary: Hsla,
    pub faint: Hsla,
    pub line: Hsla,
    pub bright: Hsla,
    pub(crate) focus: Hsla,
    pub inverse: Hsla,
    pub(crate) neutral_inverse: Hsla,
    accent: AccentPalette,
    pub danger: Hsla,
    pub success: Hsla,
}
impl Paint {
    pub fn get(cx: &App) -> Self {
        Self::for_theme(Theme::global(cx))
    }
    pub(crate) fn for_theme(theme: &Theme) -> Self {
        let mut paint = Self::for_mode(theme.mode);
        let tint = theme.accent.for_mode(theme.mode);
        if tint.is_transparent() {
            return paint;
        }
        paint.accent = theme.accent;
        paint.bright = paint.bright.blend(tint);
        paint.focus = theme.tokens.colors.focus_outline;
        paint.inverse = paint.accent.on_fill(paint.bright, paint.neutral_inverse);
        paint.hover = paint.hover.blend(tint.opacity(0.12));
        paint
    }
    pub(crate) fn primary_hover(self, strength: f32) -> Hsla {
        self.bright.blend(
            self.accent
                .hover_tint(self.bright, self.inverse, strength)
                .opacity(strength),
        )
    }
    pub fn for_mode(mode: ThemeMode) -> Self {
        let dark = mode == ThemeMode::Dark;
        let [
            stage,
            panel,
            tray,
            hover,
            ink,
            secondary,
            faint,
            line,
            bright,
            inverse,
            danger,
        ] = if dark {
            [
                0x242424, 0x191919, 0x303030, 0x353535, 0xf2f2f2, 0xb5b5b5, 0x898989, 0x2b2b2b,
                0xf2f2f2, 0x141414, 0xff746f,
            ]
        } else {
            [
                0xf5f5f5, 0xffffff, 0xffffff, 0xe9e9e9, 0x1a1a1a, 0x575757, 0x747474, 0xe2e2e2,
                0x181818, 0xfafafa, 0xbd302c,
            ]
        };
        Self {
            stage: rgb(stage).into(),
            panel: rgb(panel).into(),
            tray: rgb(tray).into(),
            hover: rgb(hover).into(),
            ink: rgb(ink).into(),
            secondary: rgb(secondary).into(),
            faint: rgb(faint).into(),
            line: rgb(line).into(),
            bright: rgb(bright).into(),
            focus: rgb(bright).into(),
            inverse: rgb(inverse).into(),
            neutral_inverse: rgb(inverse).into(),
            accent: AccentPalette::default(),
            danger: rgb(danger).into(),
            success: rgb(if dark { 0x53d986 } else { 0x008039 }).into(),
        }
    }
    pub fn colors(self, t: Tone) -> (Hsla, Hsla) {
        match t {
            Tone::Primary => (self.bright, self.inverse),
            Tone::Success => (self.panel.blend(self.success.opacity(0.10)), self.ink),
            Tone::Muted => (self.secondary, self.neutral_inverse),
            Tone::Clear => (transparent_black(), self.ink),
            _ => (self.panel, self.ink),
        }
    }
}
pub fn face(
    id: impl Into<ElementId>,
    name: impl Into<SharedString>,
    height: f32,
    r: f32,
    t: Tone,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let (bg, fg) = p.colors(t);
    let name = name.into();
    let ring = Theme::global(cx).tokens.colors.focus_outline;
    div()
        .id(id)
        .debug_selector({
            let name = name.clone();
            move || name.to_string()
        })
        .aria_label(name)
        .role(Role::Button)
        .tab_index(0)
        .h(px(height))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(8.))
        .rounded(px(r))
        .bg(bg)
        .text_color(fg)
        .text_size(px(14.))
        .line_height(px(19.6))
        .font_weight(FontWeight::MEDIUM)
        .whitespace_nowrap()
        .cursor_pointer()
        .when(t == Tone::Danger, |e| {
            e.border_1().border_color(p.danger.opacity(0.42))
        })
        .when(t == Tone::Success, |e| {
            e.border_1().border_color(p.success.opacity(0.40))
        })
        .focus_visible(move |s| s.border_1().border_color(ring))
}
/// Analytic critically damped spring. Retargeting preserves instantaneous velocity.
#[derive(Clone, Copy, Debug)]
pub struct Slide {
    from: f32,
    to: f32,
    velocity: f32,
    start: Option<Instant>,
    omega: f32,
}
impl Slide {
    pub fn new(v: f32) -> Self {
        Self {
            from: v,
            to: v,
            velocity: 0.,
            start: None,
            omega: 12.47,
        }
    }
    pub fn snappy(v: f32) -> Self {
        Self {
            omega: 20.14,
            ..Self::new(v)
        }
    }
    /// Re-express the same trajectory in a shifted coordinate system, preserving velocity.
    pub fn translate(&mut self, delta: f32) {
        self.from += delta;
        self.to += delta;
    }
    pub fn reset(&mut self, v: f32) {
        self.from = v;
        self.to = v;
        self.velocity = 0.;
        self.start = None;
    }
    pub fn set(&mut self, v: f32, cx: &App) {
        self.retarget(v, self.omega, cx);
    }
    pub fn duration(&mut self, v: f32, visual_seconds: f32, cx: &App) {
        self.retarget(v, 5.236 / visual_seconds, cx)
    }
    /// Settle a directly manipulated value with the measured release speed (units per second).
    pub(crate) fn release(&mut self, target: f32, velocity: f32, seconds: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(target);
            return;
        }
        let now = cx.background_executor().now();
        self.from = self.sample(now).0;
        self.to = target;
        self.velocity = velocity;
        self.omega = 5.236 / seconds;
        self.start = Some(now);
    }
    /// Stagger a first reveal without advancing the value before its slot starts.
    pub(crate) fn delayed(&mut self, target: f32, seconds: f32, delay: f32, cx: &App) {
        if self.to == target {
            return;
        }
        self.duration(target, seconds, cx);
        if let Some(start) = self.start.as_mut() {
            *start += std::time::Duration::from_secs_f32(delay.max(0.));
        }
    }
    fn retarget(&mut self, v: f32, omega: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(v);
            return;
        }
        if self.to == v {
            return;
        }
        let now = cx.background_executor().now();
        let (pos, vel, _) = self.sample(now);
        self.from = pos;
        self.velocity = vel;
        self.omega = omega;
        self.to = v;
        self.start = Some(now);
    }
    pub(crate) fn sample(&self, now: Instant) -> (f32, f32, bool) {
        let Some(start) = self.start else {
            return (self.to, 0., false);
        };
        let t = now.saturating_duration_since(start).as_secs_f32();
        let d = self.from - self.to;
        let k = self.velocity + self.omega * d;
        let e = (-self.omega * t).exp();
        let offset = (d + k * t) * e;
        let vel = (self.velocity - self.omega * k * t) * e;
        if offset.abs() < 0.0008 && vel.abs() < 0.012 || t > 1.6 {
            (self.to, 0., false)
        } else {
            (self.to + offset, vel, true)
        }
    }
    /// Sample several springs at one instant and let the caller schedule a single frame.
    pub(crate) fn sample_batch(&self, now: Instant, reduced: bool) -> (f32, bool) {
        if reduced {
            (self.to, false)
        } else {
            let (value, _, active) = self.sample(now);
            (value, active)
        }
    }
    /// Sample from an input handler without scheduling a frame outside paint.
    pub fn value(&self, cx: &App) -> f32 {
        if disabled_motion(cx) {
            self.to
        } else {
            self.sample(cx.background_executor().now()).0
        }
    }
    pub fn get(&self, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return self.to;
        }
        let (v, _, m) = self.sample(cx.background_executor().now());
        if m {
            w.request_animation_frame()
        }
        v
    }
}
pub fn disabled_motion(cx: &App) -> bool {
    cx.try_global::<Theme>().is_some_and(|t| t.reduced_motion)
}
/// A finite paint clock; never schedules frames once its last phase has finished.
#[derive(Clone, Copy, Default, Debug)]
pub struct PhaseClock(Option<Instant>);
impl PhaseClock {
    pub fn restart(&mut self, cx: &App) {
        self.0 = Some(cx.background_executor().now())
    }
    pub fn age(self, cx: &App) -> f32 {
        self.0.map_or(f32::INFINITY, |s| {
            cx.background_executor()
                .now()
                .saturating_duration_since(s)
                .as_secs_f32()
        })
    }
    pub fn time(self, end: f32, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return end;
        }
        let t = self.age(cx);
        if t < end {
            w.request_animation_frame()
        }
        t.min(end)
    }
}
pub fn ease(t: f32) -> f32 {
    cubic_out(t, 0.16, 0.30)
}
/// Cubic-bezier(.22, 1, .36, 1) used by page-scale wipes.
pub fn standard_ease(x: f32) -> f32 {
    cubic_out(x, 0.22, 0.36)
}
fn cubic_out(x: f32, x1: f32, x2: f32) -> f32 {
    if x <= 0. || x >= 1. {
        return x.clamp(0., 1.);
    }
    let (mut lo, mut hi) = (0., 1.);
    for _ in 0..14 {
        let t = (lo + hi) * 0.5;
        let v = 1. - t;
        let at = 3. * x1 * v * v * t + 3. * x2 * v * t * t + t * t * t;
        if at < x { lo = t } else { hi = t }
    }
    1. - (1. - (lo + hi) * 0.5_f32).powi(3)
}
pub fn measure(text: &SharedString, size: f32, w: &Window) -> f32 {
    let mut style = w.text_style();
    style.font_weight = FontWeight::MEDIUM;
    let advance: f32 = w
        .text_system()
        .shape_line(text.clone(), px(size), &[style.to_run(text.len())], None)
        .width
        .into();
    (advance - 0.01 * size * text.chars().count() as f32).max(0.)
}
/// Pointer feedback lives in the element's stable hit box, independent of its paint.
pub fn press<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    field: fn(&mut T) -> &mut Slide,
) -> Stateful<Div> {
    el.on_mouse_down(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(1., cx);
            cx.notify()
        }),
    )
    .on_mouse_up(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_mouse_up_out(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_key_down(cx.listener(move |v, e: &KeyDownEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(1., cx);
            cx.notify()
        }
    }))
    .on_key_up(cx.listener(move |v, e: &KeyUpEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(0., cx);
            cx.notify()
        }
    }))
}

/// Stable glyph identities are matched in reading order, including common suffixes.
fn shared_glyphs(
    left: &[(SharedString, f32)],
    right: &[(SharedString, f32)],
) -> Vec<Option<usize>> {
    let stride = right.len() + 1;
    let mut lcs = vec![0u16; (left.len() + 1) * stride];
    for i in (0..left.len()).rev() {
        for j in (0..right.len()).rev() {
            lcs[i * stride + j] = if left[i].0 == right[j].0 {
                1 + lcs[(i + 1) * stride + j + 1]
            } else {
                lcs[(i + 1) * stride + j].max(lcs[i * stride + j + 1])
            };
        }
    }
    let mut out = vec![None; left.len()];
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i].0 == right[j].0 {
            out[i] = Some(j);
            i += 1;
            j += 1
        } else if lcs[(i + 1) * stride + j] >= lcs[i * stride + j + 1] {
            i += 1
        } else {
            j += 1
        }
    }
    out
}
/// Paint two label phases in one measured slot; the outgoing face never affects layout.
pub fn lettering(
    old: SharedString,
    new: SharedString,
    time: f32,
    letters: bool,
    size: f32,
    ink: Hsla,
    width: f32,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, cx| {
            let plain = old == new || time >= 0.48;
            let mut style = w.text_style();
            style.font_weight = FontWeight::MEDIUM;
            let width_of = |s: &SharedString| {
                f32::from(
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None)
                        .width,
                )
            };
            let old_x = (width - width_of(&old)) * 0.5;
            let new_x = (width - width_of(&new)) * 0.5;
            if plain {
                let mut run = style.to_run(new.len());
                run.color = ink;
                let line = w
                    .text_system()
                    .shape_line(new.clone(), px(size), &[run], None);
                let _ = line.paint(
                    b.origin + point(px(new_x), px(0.)),
                    b.size.height,
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
                return;
            }
            let pieces = |s: &SharedString| -> Vec<(SharedString, f32)> {
                let line =
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None);
                s.char_indices()
                    .map(|(i, c)| (c.to_string().into(), line.x_for_index(i).into()))
                    .collect()
            };
            let mut runs = Vec::new();
            if letters && old.len() < 256 && new.len() < 256 {
                let left = pieces(&old);
                let right = pieces(&new);
                let pairs = shared_glyphs(&left, &right);
                let mut stable = vec![false; right.len()];
                let out = 1. - standard_ease(time / 0.16);
                let layout = 1. - (1. + 12.47 * time) * (-12.47 * time).exp();
                for ((glyph, dx), matched) in left.into_iter().zip(pairs) {
                    if let Some(j) = matched {
                        let x = old_x + dx;
                        stable[j] = true;
                        runs.push((glyph, x + (new_x + right[j].1 - x) * layout, 0., 1., 0.));
                    } else {
                        runs.push((glyph, old_x + dx, -3. * (1. - out), out, 2. * (1. - out)));
                    }
                }
                let mut order = 0;
                for ((glyph, dx), matched) in right.into_iter().zip(stable) {
                    if !matched {
                        let k = ease((time - (order as f32 * 0.016).min(0.1)) / 0.24);
                        runs.push((glyph, new_x + dx, 4. * (1. - k), k, 2. * (1. - k)));
                        order += 1;
                    }
                }
            } else {
                let incoming = ease(time / 0.16);
                runs.push((old.clone(), old_x, 0., 1. - standard_ease(time / 0.10), 0.));
                runs.push((new.clone(), new_x, 2. * (1. - incoming), incoming, 0.));
            }
            for (s, x, y, alpha, blur) in runs {
                if alpha < 0.001 || s.is_empty() {
                    continue;
                }
                let taps = if blur > 0.22 { 5 } else { 1 };
                let mut run = style.to_run(s.len());
                run.color = ink.opacity(alpha / if taps == 5 { 4.3 } else { 1. });
                let line = w.text_system().shape_line(s, px(size), &[run], None);
                for (dx, dy) in [(0., 0.), (-0.7, 0.), (0.7, 0.), (0., -0.7), (0., 0.7)]
                    .into_iter()
                    .take(taps)
                {
                    let _ = line.paint(
                        b.origin + point(px(x + dx * blur), px(y + dy * blur)),
                        b.size.height,
                        TextAlign::Left,
                        None,
                        w,
                        cx,
                    );
                }
            }
        },
    )
    .w(px(width.max(0.)))
    .h(px(size * 1.4))
    .flex_none()
}

#[cfg(test)]
mod spring_tests {
    use super::{Instant, Slide};
    use std::time::Duration;
    #[test]
    fn reversing_keeps_position_and_velocity() {
        let s = Instant::now();
        let mid = s + Duration::from_millis(75);
        let a = Slide {
            start: Some(s),
            to: 1.,
            ..Slide::new(0.)
        };
        let (x, v, _) = a.sample(mid);
        let reversed = Slide {
            start: Some(mid),
            from: x,
            velocity: v,
            to: 0.,
            ..a
        };
        assert_eq!(reversed.sample(mid), (x, v, true));
        assert_eq!(reversed.sample_batch(mid, false), (x, true));
        assert_eq!(reversed.sample_batch(mid, true), (0., false));
        assert!(reversed.sample(mid + Duration::from_millis(240)).0 < x);
        assert_eq!(
            reversed.sample(mid + Duration::from_secs(2)),
            (0., 0., false)
        );
    }
    #[test]
    fn unchanged_suffix_keeps_its_identity_across_label_swaps() {
        let glyphs = |s: &str| {
            s.chars()
                .map(|g| (gpui::SharedString::from(g.to_string()), 0.))
                .collect::<Vec<_>>()
        };
        let old = glyphs("Add to library");
        let new = glyphs("In library");
        let pairs = super::shared_glyphs(&old, &new);
        assert_eq!(
            &pairs[old.len() - 7..],
            &[
                Some(3),
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(8),
                Some(9)
            ]
        );
        assert_eq!(
            super::shared_glyphs(&glyphs("添加成员"), &glyphs("移除成员")),
            vec![None, None, Some(2), Some(3)]
        );
    }
}

#[cfg(test)]
mod accent_tests {
    use super::{AccentPalette, Paint, Theme, ThemeMode};
